import numpy as np, json, os,re
from collections import Counter
from scipy.ndimage import label
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(Ig):
    I=np.array(Ig); H,W=I.shape
    cnt=Counter(I.ravel()); bg=cnt.most_common(1)[0][0]
    bigmask=(I!=bg)
    lab,n=label(bigmask)
    markers=[]; patcells=None
    for i in range(1,n+1):
        pts=set(map(tuple,np.argwhere(lab==i)))
        if len(pts)==1: markers.append(pts.pop())
        else: patcells=pts
    pat=[[int(I[r,c]) if int(I[r,c])!=0 else 0 for c in range(min(p[1] for p in patcells),max(p[1] for p in patcells)+1)] for r in range(min(p[0] for p in patcells),max(p[0] for p in patcells)+1)]
    O=I.copy(); ph,pw=len(pat),len(pat[0])
    for sr,sc in markers:
        for a in range(ph):
            for b in range(pw):
                rr,cc=sr+(a-ph//2), sc+(b-pw//2)
                if 0<=rr<H and 0<=cc<W: O[rr,cc]=pat[a][b]
    return O.tolist()
